      'dades.invNoRows': 'Cap mostra',
      'dades.invLegend': 'El retard es mesura per viatge: quan el bus comença un viatge nou es torna a comptar. «Pas»: l\'hora del darrer registre del bus abans de passar per la parada, és a dir, quan hi va arribar (el primer registre, camí de la parada, és a l\'indicador en passar-hi el ratolí). «Teòric → Real»: l\'operador només envia el retard; l\'hora teòrica és la de l\'horari publicat per a aquell viatge i la real és la teòrica més el retard. «Senyal»: GPS si la posició era recent, Estimat si el bus havia perdut el senyal uns segons. «▲»: minuts de retard que el bus va guanyar en aquell punt.',
