      'dades.stWhyUnknown': 'No hi ha dades de senyal d\'aquest tram (les posicions només es guarden unes hores i els talls de GPS només es registren des que existeix aquest control), així que no es pot saber si és un escurçament del recorregut, una pèrdua de senyal o una reassignació del sistema. El retard no es va recuperar en ruta.',
