      'dades.incInvDesc': 'Aquests registres presenten un retard de 25 minuts o més. No es consideren retencions habituals de trànsit de la ciutat, sinó <strong>horaris no normals o possibles incidències de seguiment/telemetria</strong> (com ara autobusos aturats fora de servei en capçalera amb el SAE encès, talls excepcionals de carrer o desfasaments de torn). Estan pendents d\'investigació per resoldre la seva causa real.',
