      'dades.incAnomTitle': 'Anomalies de Telemetria SAE & Sortida de Cotxeres ({n})',
      'dades.incAnomDesc': 'Aquests registres no corresponen a retencions de trànsit de la ciutat, sinó a <strong>desfasaments de telemetria generats pel sistema SAE (CAD/AVL) d\'Avanza</strong> fora de l\'horari publicat de cada línia (sortides i tornades a cotxeres) o amb 10 min o més durant la primera mitja hora de servei de la línia (un bus que comença torn assignat a una expedició anterior). També hi apareixen els <strong>viatges reassignats pel SAE</strong> (🔀): trams on el retard desapareix de cop perquè el sistema tenia el bus assignat a un viatge que no feia, i els <strong>salts de retard impossibles</strong> (⏫): el retard puja més de pressa que passa el temps perquè el sistema passa el bus a una expedició anterior. També els <strong>recorreguts en sentit invers</strong> (⏪): el bus torna enrere pel recorregut mentre el sistema segueix anotant el mateix retard. Es publiquen aquí per facilitar l\'auditoria i la seva correcció per part de l\'Ajuntament de Mataró.',
      'dades.incAnomCopyTip': 'Copiar resum d\'anomalies per a informe o reclamació a l\'Ajuntament / Avanza',
