      'dades.repAnomTotal': 'Total anomalies detectades: {n}',
      'dades.repAnomDesc': 'Descripció: Aquests registres corresponen a desfasaments transmesos pel sistema SAE (CAD/AVL) d\'Avanza (habitualment per assignació d\'autobusos que inicien torn a expedicions anteriors no cobertes o arrencada a cotxeres amb consola encesa abans de sortida). No reflecteixen retencions de trànsit reals a la ciutat. També inclou els viatges reassignats pel SAE: trams on el retard desapareix de cop perquè el sistema tenia el bus assignat a un viatge que no feia. I les tornades sense servei: parades anotades mentre un bus tornava sense passatgers a l\'inici de la línia després de saltar-se un viatge. I els salts de retard impossibles: el retard puja més de pressa que passa el temps perquè el sistema passa el bus a una expedició anterior. I els recorreguts en sentit invers: el bus torna enrere pel recorregut mentre el sistema segueix anotant el mateix retard.',
