      'dades.methIndepTitle': '🎯 Medición independiente de retrasos',
      'dades.methIndepText': 'Además de recoger el retraso informado por el operador (SIRI), Arribo! mide con el GPS el instante real de paso ante la parada y lo compara con la hora publicada de la expedición que indica el operador. La tasa de concordancia (diferencia ≤ 1 min) valida el reloj, no la expedición: por eso se informa aparte cuántos pasos tienen como expedición más cercana la misma que indica el operador.',
