      'dades.incInvDesc': 'Estos registros presentan un retraso de 25 minutos o más. No se consideran retenciones habituales de tráfico de la ciudad, sino <strong>horarios no normales o posibles incidencias de seguimiento/telemetría</strong> (como autobuses parados fuera de servicio en cabecera con el SAE encendido, cortes excepcionales de calle o desfases de turno). Están pendientes de investigación para resolver su causa real.',
