      'dades.incAnomTitle': 'Anomalías de Telemetría SAE y Salida de Cocheras ({n})',
      'dades.incAnomDesc': 'Estos registros no corresponden a retenciones de tráfico de la ciudad, sino a <strong>desfases de telemetría generados por el sistema SAE (CAD/AVL) de Avanza</strong> fuera del horario publicado de cada línea (salidas y regresos a cocheras) o con 10 min o más durante la primera media hora de servicio de la línea (un bus que inicia turno asignado a una expedición anterior). También aparecen los <strong>viajes reasignados por el SAE</strong> (🔀): tramos donde el retraso desaparece de golpe porque el sistema tenía el bus asignado a un viaje que no hacía, y los <strong>saltos de retraso imposibles</strong> (⏫): el retraso sube más deprisa de lo que pasa el tiempo porque el sistema pasa el bus a una expedición anterior. También los <strong>recorridos en sentido inverso</strong> (⏪): el bus retrocede por el recorrido mientras el sistema sigue anotando el mismo retraso. Se publican aquí para facilitar la auditoría y su corrección por parte del Ayuntamiento de Mataró.',
