      'dades.methExpand': 'Expand ▾',
      'dades.methCollapse': 'Collapse ▴',
      'dades.methSourceTitle': '📡 Data source & telemetry',
      'dades.methSourceText': 'Data comes from the official real-time telemetry feed (SIRI) of Mataró Bus Urbà operated by Avanza. Arribo! polls every bus’s position and delay continuously every 20 seconds.',
      'dades.methUnitTitle': '📍 Unit of analysis: Stop visits',
      'dades.methUnitPre': 'The unit of analysis is the ',
      'dades.methUnitEm': 'stop visit',
      'dades.methUnitPost': ' (one vehicle serving one specific stop). Consecutive readings from the same bus while approaching or dwelling at a stop are consolidated into a single visit, so queues or traffic jams do not artificially inflate sample counts.',
      'dades.methThreshTitle': '⏱️ Official punctuality thresholds',
      'dades.methOnTimeLbl': 'On time:',
      'dades.methOnTimePre': ' delay between ',
      'dades.methOnTimeRange': '-1 and +3 minutes',
      'dades.methEarlyLbl': 'Early:',
      'dades.methEarlyPre': ' more than 1 minute ahead of schedule (',
      'dades.methEarlyRange': '< -1 min',
      'dades.methEarlyPost': '). A bus that passes early is not on time because riders arriving for the published time miss it.',
      'dades.methLateLbl': 'Late:',
      'dades.methLatePre': ' over 3 minutes late (',
      'dades.methLateRange': '> 3 min',
      'dades.methSevereLbl': 'Severe delay:',
      'dades.methSeverePre': ' 5 minutes or more (',
      'dades.methSevereRange': '≥ 5 min',
      'dades.methSchedTitle': '📅 Reference timetables & season',
      'dades.methSchedPre': 'Arrivals are compared against the official timetable published on ',
      'dades.methSchedPost': ' for each specific trip, automatically applying the active seasonal calendar (summer/winter) and day type (weekday, Saturday or public holiday).',
      'dades.methIndepTitle': '🎯 Independent delay measurement',
      'dades.methIndepText': 'In addition to collecting the delay reported by the operator (SIRI), Arribo! measures the actual passing time at the stop from GPS and compares it with the published time of the trip the operator indicates. The agreement rate (difference ≤ 1 min) validates the clock, not the trip assignment: that is why we separately report how many visits independently match the operator’s trip as the nearest departure.',
      'dades.methLimitsLbl': 'Known limitations:',
      'dades.methLimitsPre': ' Gaps can occur if the operator’s feed suffers outages (visible in the ',
      'dades.methLimitsLink': 'system status',
      'dades.methLimitsPost': '). Buses not transmitting GPS cannot be measured. Reported delays come from the operating company’s own systems.',
