      'dades.incAnomTitle': 'CAD/AVL Telemetry & Depot Pull-out Anomalies ({n})',
      'dades.incAnomDesc': 'These records do not reflect city traffic congestion, but <strong>telemetry offsets produced by Avanza’s CAD/AVL (SAE) system</strong> outside each line’s published operating hours (depot pull-outs and pull-ins) or ≥10 min during the first half-hour of service (a bus starting its shift assigned to an earlier trip). Also included: <strong>reassigned trips</strong> (🔀), where delay vanishes abruptly because the system had the bus on the wrong trip; <strong>impossible delay jumps</strong> (⏫), where delay grows faster than elapsed time after reassigning to an earlier trip; and <strong>backward route legs</strong> (⏪), where the bus moves backwards while delay stays frozen. Published here to aid auditing and fixes by Mataró City Council.',
